package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type SchedRec struct { // 01 SCHED-REC, 16 bytes
	ScAcct  string          // PIC X(4) @0 len=4
	ScPrin  decimal.Decimal // PIC 9(5)V99 @4 len=7
	ScRate  decimal.Decimal // PIC 9(2)V99 @11 len=4
	ScYears int64           // PIC 9(1) @15 len=1
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string // PIC X len=1 = "N"
var WsBal decimal.Decimal // PIC 9(8)V99 len=10 = 0
var WsYear int64 // PIC 99 len=2 = 0
var WsCount int64 // PIC 99 len=2 = 0
var WsBalEd string // PIC ZZ,ZZZ,ZZ9.99 len=13

var SchedRecData SchedRec

var schedFile *os.File
var schedScanner *bufio.Scanner

func init() {
	WsEofFlag = "N"
	WsBal = decimal.NewFromInt(0)
	WsYear = 0
	WsCount = 0
	WsBalEd = ""
}

func InputDone() bool {
	return WsEofFlag == "Y"
}

func parsePic9V99(s string, scale int32) decimal.Decimal {
	t := strings.TrimSpace(s)
	if t == "" {
		return decimal.NewFromInt(0)
	}
	// digits only, implied decimal
	// allow optional sign? just parse
	var neg bool
	if len(t) > 0 && (t[0] == '+' || t[0] == '-') {
		if t[0] == '-' {
			neg = true
		}
		t = t[1:]
		if strings.TrimSpace(t) == "" {
			return decimal.NewFromInt(0)
		}
	}
	// t should be digits; if contains spaces inside, remove them?
	t = strings.TrimSpace(t)
	var n int64
	for i := 0; i < len(t); i++ {
		c := t[i]
		if c >= '0' && c <= '9' {
			n = n*10 + int64(c-'0')
		} else if c == ' ' {
			continue
		} else {
			// non-numeric: treat as zero
			return decimal.NewFromInt(0)
		}
	}
	if neg {
		n = -n
	}
	return decimal.New(n, -scale)
}

func parsePic9(s string) int64 {
	t := strings.TrimSpace(s)
	if t == "" {
		return 0
	}
	var neg bool
	if t[0] == '+' || t[0] == '-' {
		if t[0] == '-' {
			neg = true
		}
		t = t[1:]
		if t == "" {
			return 0
		}
	}
	var n int64
	for i := 0; i < len(t); i++ {
		c := t[i]
		if c >= '0' && c <= '9' {
			n = n*10 + int64(c-'0')
		} else if c == ' ' {
			continue
		} else {
			return 0
		}
	}
	if neg {
		n = -n
	}
	return n
}

func formatPic99(v int64) string {
	m := v % 100
	if m < 0 {
		m += 100
	}
	return fmt.Sprintf("%02d", m)
}

func formatWsBalEd(v decimal.Decimal) string {
	av := v
	if av.IsNegative() {
		av = av.Abs()
	}
	cents := av.Shift(2).IntPart()
	const mod int64 = 10000000000
	centsMod := cents % mod
	if centsMod < 0 {
		centsMod += mod
	}
	intPart := centsMod / 100
	fracPart := centsMod % 100
	var d [8]int64
	tmp := intPart
	for i := 7; i >= 0; i-- {
		d[i] = tmp % 10
		tmp /= 10
	}
	f1 := fracPart / 10
	f2 := fracPart % 10
	firstSig := -1
	for i := 0; i < 8; i++ {
		if d[i] != 0 {
			firstSig = i
			break
		}
	}
	outIdx := []int{0, 1, 3, 4, 5, 7, 8, 9}
	var out [13]byte
	for i := 0; i < 8; i++ {
		var ch byte
		if i == 7 {
			ch = byte('0' + d[i])
		} else {
			if firstSig == -1 || i < firstSig {
				ch = ' '
			} else {
				ch = byte('0' + d[i])
			}
		}
		out[outIdx[i]] = ch
	}
	if firstSig == -1 || firstSig > 1 {
		out[2] = ' '
	} else {
		out[2] = ','
	}
	if firstSig == -1 || firstSig > 4 {
		out[6] = ' '
	} else {
		out[6] = ','
	}
	out[10] = '.'
	out[11] = byte('0' + f1)
	out[12] = byte('0' + f2)
	return string(out[:])
}

func storeWsBal(v decimal.Decimal) decimal.Decimal {
	cents := v.Shift(2).IntPart()
	const mod int64 = 10000000000
	centsMod := cents % mod
	return decimal.New(centsMod, -2)
}

func MainPara() {
	var err error
	schedFile, err = os.Open("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, "error opening input.dat:", err)
		os.Exit(1)
	}
	schedScanner = bufio.NewScanner(schedFile)
	ReadPara()
	for !InputDone() {
		ProcessPara()
	}
	schedFile.Close()
	fmt.Printf("SCHEDULES: %s\n", formatPic99(WsCount))
}

func ReadPara() {
	if schedScanner.Scan() {
		line := schedScanner.Text()
		if len(line) < 16 {
			line += strings.Repeat(" ", 16-len(line))
		} else if len(line) > 16 {
			line = line[:16]
		}
		SchedRecData.ScAcct = line[0:4]
		SchedRecData.ScPrin = parsePic9V99(line[4:11], 2)
		SchedRecData.ScRate = parsePic9V99(line[11:15], 2)
		SchedRecData.ScYears = parsePic9(line[15:16])
	} else {
		if err := schedScanner.Err(); err != nil {
			fmt.Fprintln(os.Stderr, "error reading input.dat:", err)
			os.Exit(1)
		}
		WsEofFlag = "Y"
	}
}

func ProcessPara() {
	WsBal = SchedRecData.ScPrin
	WsYear = 1
	for !(WsYear > SchedRecData.ScYears) {
		rateDiv := SchedRecData.ScRate.Shift(-2)
		factor := decimal.NewFromInt(1).Add(rateDiv)
		prod := WsBal.Mul(factor)
		rounded := prod.Round(2)
		WsBal = storeWsBal(rounded)
		WsBalEd = formatWsBalEd(WsBal)
		fmt.Printf("%s Y%s %s\n", SchedRecData.ScAcct, formatPic99(WsYear), WsBalEd)
		WsYear = (WsYear + 1) % 100
	}
	WsBalEd = formatWsBalEd(WsBal)
	fmt.Printf("%s FINAL %s\n", SchedRecData.ScAcct, WsBalEd)
	WsCount = (WsCount + 1) % 100
	ReadPara()
}

func main() {
	MainPara()
}
